// このファイルは scripts/generate-rules.mjs が rules/skill_rules.toml から自動で作ります。直接編集しないでください。
export const SKILL_RULES_TOML: string = "# =============================================================================\n# 鑑定スキル表・判定の要点の「解釈ルール」設定ファイル\n#\n# このファイルを書き換えると、次の2つに反映されます（サーバーの再起動は不要）。\n#   1. 鑑定スキル表の点数（[[rules]] の adjust による補正）\n#   2. 判定の要点（AI解説）に渡す解釈（principles・day_stems・[[rules]] の interpretation）\n#\n# 書き方の詳細: doc/解釈ルール設定.md\n# 書き換えたら version の日付を更新してください（AI解説のキャッシュは内容が変われば自動で別扱いになります）。\n#\n# ※ 初期の内容は、四柱推命の一般的な考え方で作った「叩き台」です。\n#    陽てん塾の流儀に合わせて自由に書き換えてください。\n# =============================================================================\n\nversion = \"2026-11-06\"\n\n# -----------------------------------------------------------------------------\n# AI解説の読み方の原則（上から順に重要。AIへの指示にそのまま入ります）\n# -----------------------------------------------------------------------------\nprinciples = [\n  \"日干を最重要の起点にする。まず day_stem（日干の五行・陰陽・性質）を確認し、すべての解説を「この日干の人にとって」という視点で組み立てる。\",\n  \"五行の点数は量だけでなく、日干から見た関係も読む。element_relations の relation（日干を生じる／日干を剋す など）と role（喜＝日干の助けになる、忌＝負担・過剰になりやすい、中＝どちらにも働く）を必ず踏まえる。\",\n  \"同じ五行が多くても、日干にとって忌であれば「強み」ではなく「重さ・プレッシャー・偏り」として出ることがある。身旺・身弱（strength）による効き方の違いを明確に書く。\",\n  \"applied_rules は判定ルールで確定した解釈であり、点数の補正もこのルールによる。該当する能力・職種の説明では、必ずこの解釈を根拠に使う。\",\n  \"「○○の五行が多いから○○が高い」と点数を言い換えるだけで終わらせない。他の五行との総合的なバランスを考えた解釈をすること。\",\n]\n\n# -----------------------------------------------------------------------------\n# 身旺・身弱ごとの、日干から見た各五行グループの役割\n#   喜 = 日干の助けになる（強めたい）／ 忌 = 過剰・負担になりやすい ／ 中 = どちらにも働く\n#   アプリの命式画面の説明（身旺は食傷・財を強める、身弱は比劫・印を強める、官は中立）に合わせている\n# -----------------------------------------------------------------------------\n[strength_roles.\"身旺\"]\n\"比劫\" = \"忌\"\n\"印\" = \"忌\"\n\"食傷\" = \"喜\"\n\"財\" = \"喜\"\n\"官\" = \"中\"\n\n[strength_roles.\"身弱\"]\n\"比劫\" = \"喜\"\n\"印\" = \"喜\"\n\"食傷\" = \"忌\"\n\"財\" = \"忌\"\n\"官\" = \"中\"\n\n[strength_roles.\"中和\"]\n\"比劫\" = \"中\"\n\"印\" = \"中\"\n\"食傷\" = \"中\"\n\"財\" = \"中\"\n\"官\" = \"中\"\n\n# -----------------------------------------------------------------------------\n# 日干ごとの性質（AI解説の起点。nature=本質、strengths=出やすい強み、cautions=注意点）\n# adjust を書くと、その日干の人の点数にも補正をかけられる（書き方は [[rules]] と同じ）\n# -----------------------------------------------------------------------------\n[day_stems.\"甲\"]\nnature = \"大樹。まっすぐ上に伸びようとする向上心と、筋を通す芯の強さを持つ。\"\nstrengths = \"目標に向かって伸び続ける力、頼られる親分肌、物事を始める力\"\ncautions = \"曲がることが苦手で、方針転換や妥協に時間がかかりやすい\"\n\n[day_stems.\"乙\"]\nnature = \"草花・つる草。しなやかに環境へ合わせ、人とのつながりを伝って広がる。\"\nstrengths = \"柔軟性、協調性、踏まれても立ち直る粘り強さ、縁を活かす力\"\ncautions = \"周囲に合わせすぎて、自分で決めることを後回しにしやすい\"\n\n[day_stems.\"丙\"]\nnature = \"太陽。明るく開放的で、周囲を照らし人を集める。\"\nstrengths = \"発信力、明るさ、場を盛り上げる力、裏表のなさ\"\ncautions = \"勢いで進めて細部や継続が粗くなりやすい\"\n\n[day_stems.\"丁\"]\nnature = \"灯火。内に熱を秘め、身近な人や一点を照らし続ける。\"\nstrengths = \"洞察力、集中力、一人ひとりへの細やかな配慮、技を磨く力\"\ncautions = \"感情の波が出やすく、気にしすぎて消耗しやすい\"\n\n[day_stems.\"戊\"]\nnature = \"山。どっしりと動かず、人や物を受け止める包容力を持つ。\"\nstrengths = \"安定感、信頼感、受け止める力、物事を長く維持する力\"\ncautions = \"腰が重く、変化への対応や決断が遅れやすい\"\n\n[day_stems.\"己\"]\nnature = \"田畑。種を受け止めて育て、実りに変える。\"\nstrengths = \"人や物事を育てる力、面倒見、実務の多才さ、吸収力\"\ncautions = \"何でも受け止めて抱え込み、迷いやすい\"\n\n[day_stems.\"庚\"]\nnature = \"鉄・鉱石。硬く強い素材で、火（官）に鍛えられて道具や刀になる。\"\nstrengths = \"決断力、行動力、正義感、鍛えられて伸びる力、技術の習得\"\ncautions = \"不器用で融通が利きにくく、鍛える場（規律・目標）がないと力を持て余す\"\n\n[day_stems.\"辛\"]\nnature = \"宝石・貴金属。磨かれて輝き、美しさや品質にこだわる。\"\nstrengths = \"美意識、品質へのこだわり、繊細な感性、プライドを力に変える\"\ncautions = \"傷つきやすく、完璧を求めて動けなくなりやすい\"\n\n[day_stems.\"壬\"]\nnature = \"大河・海。スケールが大きく、止まらず流れ続ける。\"\nstrengths = \"発想の大きさ、自由さ、知恵、状況に合わせて形を変える力\"\ncautions = \"流されやすく、締まりや継続に欠けやすい\"\n\n[day_stems.\"癸\"]\nnature = \"雨・露。静かに染み込み、周囲を潤す。\"\nstrengths = \"静かな知性、浸透力、裏方で支える力、忍耐\"\ncautions = \"自己主張が控えめで、押しの強さや持久力は出にくい\"\n\n# =============================================================================\n# 判定ルール\n#\n# when（条件）をすべて満たすと、そのルールが適用されます。\n#   ※ TOML では日本語の項目名を \"財\" のように引用符で囲みます。\n#   strength          = [\"身弱\"]              身旺・身弱・中和のいずれか\n#   day_stem          = [\"庚\", \"辛\"]          日干\n#   day_element       = [\"金\"]                日干の五行（木・火・土・金・水）\n#   top_group         = \"官\"                  そのグループが5つの中で最大（同点も含む）\n#   group_at_least    = { \"財\" = 30 }           グループの点数がその値以上\n#   group_below       = { \"官\" = 10 }           グループの点数がその値未満\n#   group_rank_within = { \"食傷\" = 2 }          グループの順位がその値以内\n#   strength_diff_at_least / strength_diff_below = 数値   身旺度（比劫＋印 −（食傷＋財＋官））\n#   kakukyoku_any     = [\"偏官格\"]            格局にいずれかの格名を含む\n#   stem_stars        = [[\"傷官\"], [\"正官\", \"偏官\"]]\n#                       天干（日干を除く）に、各リストの星が1つ以上ずつある\n#\n# interpretation（解釈）: AI解説に渡す文。{財} {官} {身旺度} などで点数を差し込める。\n#\n# adjust（点数補正）: 能力の点数に足し引きする。表の「内訳」にはルールの title で記録される。\n#   ability = 能力（kikaku 企画 / chiryaku 知略 / jikkou 実行 / tairyoku 体力 / jinbou 人望 /\n#             touritsu 統率 / kaitaku 開拓 / shousai 商才 / kanri 管理）\n#   value   = 足す点数（マイナスで減点）\n#   per     = 掛ける元の値（省略時は value をそのまま足す）。五行グループ名（比劫・印・食傷・財・官）、\n#             通変星名（比肩〜印綬）、\"身旺度\"、またはそれらのリスト（合計に掛ける）\n#   min / max = 補正量の下限・上限\n# =============================================================================\n\n# --- 日干と五行の関係による解釈（点数補正あり） --------------------------------\n\n[[rules]]\nid = \"mijaku_kan_heavy\"\ntitle = \"身弱で官が重い（身弱殺重）\"\nwhen = { strength = [\"身弱\"], top_group = \"官\" }\ninterpretation = \"官（日干を剋す、規律・組織の力）が {官} と最も強いが、日干は身弱で受け止める力が足りない。官は人を率いる力ではなく、外から課される規律やプレッシャーとして働きやすい。自ら先頭に立つより、ルールや段取りを守り整える側で力が出やすい。\"\nadjust = [\n  { ability = \"touritsu\", per = \"官\", value = -1.0 },\n  { ability = \"touritsu\", per = [\"正官\", \"偏官\"], value = -0.3 },\n  { ability = \"kaitaku\", per = \"偏官\", value = -0.5 },\n  { ability = \"kanri\", per = \"官\", value = 0.3, max = 25 },\n]\n\n[[rules]]\nid = \"mijaku_stamina\"\ntitle = \"身弱による体力・持続力の補正\"\nwhen = { strength = [\"身弱\"] }\ninterpretation = \"日干を支える比劫・印に対して、日干の力を使う食傷・財・官が多い（身旺度 {身旺度}）。長時間動き続ける体力や持続力は出にくく、休息や役割分担を前提にすると力を保ちやすい。\"\nadjust = [\n  { ability = \"tairyoku\", per = \"身旺度\", value = 0.3, min = -30 },\n  { ability = \"jikkou\", per = \"身旺度\", value = 0.1, min = -10 },\n]\n\n[[rules]]\nid = \"mijaku_zai_heavy\"\ntitle = \"身弱で財が重い（財多身弱）\"\nwhen = { strength = [\"身弱\"], top_group = \"財\" }\ninterpretation = \"財（日干が剋す、お金・成果を扱う力）が {財} と最も強いが、日干は身弱で持ちきれない。お金や案件は回ってくるが、抱えきれずに手放しやすい。\"\nadjust = [\n  { ability = \"shousai\", per = \"財\", value = -0.5 },\n]\n\n[[rules]]\nid = \"mijaku_shokushou_heavy\"\ntitle = \"身弱で食傷が重い（洩身太過）\"\nwhen = { strength = [\"身弱\"], top_group = \"食傷\" }\ninterpretation = \"食傷（日干が生じる、表現・出力の力）が {食傷} と最も強く、身弱の日干から力が流れ出やすい。アイデアや発信は豊富だが、出し続けると消耗しやすい。\"\nadjust = [\n  { ability = \"tairyoku\", per = \"食傷\", value = -0.2, min = -15 },\n]\n\n[[rules]]\nid = \"zai_in_conflict\"\ntitle = \"財と印がともに強い（財印相剋）\"\nwhen = { group_at_least = { \"財\" = 30, \"印\" = 30 } }\ninterpretation = \"財（お金・成果を扱う力）{財} と印（学び・信用の力）{印} がともに強く、財は印を剋すためぶつかり合う配置。お金の扱いに迷いや揺れが出やすく、学びや技術を稼ぎに素直につなげにくい。\"\nadjust = [\n  { ability = \"shousai\", per = \"財\", value = -0.6 },\n  { ability = \"kanri\", value = -10 },\n]\n\n[[rules]]\nid = \"kan_weak\"\ntitle = \"官が弱い\"\nwhen = { group_below = { \"官\" = 10 } }\ninterpretation = \"官（規律・組織の力）が {官} と弱い。期限・規程・組織運営などの「枠」を自分で保つのは得意ではなく、仕組みや人に任せると安定する。\"\nadjust = [\n  { ability = \"kanri\", value = -10 },\n  { ability = \"touritsu\", value = -5 },\n]\n\n# --- 注記（点数補正なし。AI解説の根拠として渡す） --------------------------------\n\n[[rules]]\nid = \"shokan_kenkan\"\ntitle = \"傷官見官\"\nwhen = { stem_stars = [[\"傷官\"], [\"正官\", \"偏官\"]] }\ninterpretation = \"天干に傷官と官星が並ぶ（傷官見官）。既存のルールや上下関係に反発しやすく、自分自身の管理や客観視が弱まりやすい。\"\n\n[[rules]]\nid = \"in_dominant\"\ntitle = \"印が最も強い身旺\"\nwhen = { strength = [\"身旺\"], top_group = \"印\" }\ninterpretation = \"印が最も強い身旺（印 {印}）：学びが厚い一方、考えすぎて出力が遅れやすい。\"\n\n[[rules]]\nid = \"zai_scarce\"\ntitle = \"財星がほぼない\"\nwhen = { group_below = { \"財\" = 5 } }\ninterpretation = \"財星がほぼない（財 {財}）。お金や数字を扱う仕組みは意識して補う必要がある。\"\n\n[[rules]]\nid = \"kan_scarce\"\ntitle = \"官星がほぼない\"\nwhen = { group_below = { \"官\" = 5 } }\ninterpretation = \"官星がほぼない（官 {官}）。\"\n\n[[rules]]\nid = \"shokushou_strong\"\ntitle = \"食傷が強い\"\nwhen = { group_at_least = { \"食傷\" = 20 }, group_rank_within = { \"食傷\" = 2 } }\ninterpretation = \"食傷が強い（食傷 {食傷}）：表現・制作の出口が太い。\"\n";
